{
  "correction_rules": [
    "Adjust forecasts downward when sentiment history shows sustained negative sentiment (e.g., multiple -0.25 or 0.00 values), indicating market pessimism.",
    "Increase forecast sensitivity to recent price spikes — if true outcome exceeds model forecast by >5% after a spike, adjust next period’s forecast upward by 10-15% to capture momentum.",
    "Apply mean reversion bias: if model consistently overpredicts prices in 3-5 consecutive days, reduce forecast by 2-5% per day to align with historical volatility patterns.",
    "Lag correction: if true outcome is significantly higher than model forecast 2-3 days after a price spike, assume delayed market reaction — adjust forecast for next period by +3-5% to account for lagged momentum.",
    "Use sentiment as a volatility filter: if sentiment > 0.50 for 2+ consecutive days, increase forecast variance by 10% to reflect heightened market uncertainty or speculative activity.",
    "Avoid over-optimism in early periods: if model forecasts are consistently 10%+ above true outcome for 3+ consecutive days, reduce forecast by 5-10% to prevent overestimation of upward momentum."
  ]
}
